func testChecklistToManyAddOpCKLChecklistItens(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Checklist
	var b, c, d, e ChecklistIten

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, checklistDBTypes, false, strmangle.SetComplement(checklistPrimaryKeyColumns, checklistColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ChecklistIten{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, checklistItenDBTypes, false, strmangle.SetComplement(checklistItenPrimaryKeyColumns, checklistItenColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*ChecklistIten{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddCKLChecklistItens(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.CKLID != first.CKLID {
			t.Error("foreign key was wrong value", a.CKLID, first.CKLID)
		}
		if a.CKLID != second.CKLID {
			t.Error("foreign key was wrong value", a.CKLID, second.CKLID)
		}

		if first.R.CKL != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.CKL != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.CKLChecklistItens[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.CKLChecklistItens[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.CKLChecklistItens().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
func testChecklistToOneProcessoUsingPRC(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Checklist
	var foreign Processo

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, checklistDBTypes, false, checklistColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Checklist struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, processoDBTypes, false, processoColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Processo struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	local.PRCID = foreign.PRCID
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.PRC().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if check.PRCID != foreign.PRCID {
		t.Errorf("want: %v, got %v", foreign.PRCID, check.PRCID)
	}

	ranAfterSelectHook := false
	AddProcessoHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *Processo) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := ChecklistSlice{&local}
	if err = local.L.LoadPRC(ctx, tx, false, (*[]*Checklist)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.PRC == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.PRC = nil
	if err = local.L.LoadPRC(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.PRC == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

